// The scrape either produced real page text or the run stops. Nothing downstream can profile a
// business, and in lite nothing can build a prompt, from an empty page.
const MIN_SITE_MARKDOWN_CHARS = 200;

const config = $('Normalize Onboarding Input').first().json;
const res = $input.first();

if (!httpOk(res)) {
  throw new Error('Could not read ' + config.website + ': AnyAPI web.scrape returned ' + httpStatus(res) + ' ' + httpErrorCode(res));
}
if (!httpFound(res)) {
  throw new Error('Could not read ' + config.website + ': web.scrape returned no page. Check the URL is public.');
}

const data = httpData(res) || {};
const markdown = String(data.markdown || '');
if (markdown.length < MIN_SITE_MARKDOWN_CHARS) {
  throw new Error('Read ' + config.website + ' but only got ' + markdown.length + ' characters of text');
}

return [{
  json: Object.assign({}, config, {
    cost_usd: Number(config.cost_usd || 0) + httpCost(res),
    site_title: String(data.title || ''),
    site_description: String(data.description || ''),
    site_markdown: markdown,
    site_raw_html: String(data.rawHtml || ''),
  }),
}];

