// Lite has no model. It builds the same prompt shapes from what you typed on the form, so the
// rest of the workflow is identical. These are the question shapes that make an engine cite a
// third-party roundup instead of your own site.
const config = $input.first().json;
const year = new Date().getUTCFullYear();
const category = config.category;
const competitors = config.competitors.filter((c) => !config.aliases.some((a) => a.toLowerCase() === c.toLowerCase()));
if (competitors.length === 0) throw new Error('Every competitor you listed is one of your own names');

const prompts = ['best ' + category + ' tools', 'top ' + category + ' software ' + year];
if (config.icp) prompts.push('best ' + category + ' for ' + config.icp);
if (config.country && config.country !== 'US') prompts.push('best ' + category + ' in ' + config.country);
competitors.forEach((c) => prompts.push('alternatives to ' + c));
if (competitors.length > 1) prompts.push(competitors[0] + ' vs ' + competitors[1]);

const buyerPrompts = prompts
  .map((p) => p.replace(/\s+/g, ' ').trim())
  .filter((p) => !config.aliases.some((a) => p.toLowerCase().indexOf(a.toLowerCase()) !== -1))
  .filter((v, i, a) => a.indexOf(v) === i);

