  json: Object.assign({}, config, {
    business: config.brand,
    category: category,
    icp: config.icp,
    value_prop: config.site_description || '',
    buyer_prompts: buyerPrompts,
    rejected_prompts: [],
    competitors: competitors,
    profile_source: 'form',
  }),
}];

