// before a single engine call goes out.

// Verified customer prices, from the AnyAPI registry manifests. Ceilings where a SKU has lanes.
const PRICE_BRAND_VISIBILITY_USD = 0.0045;
const PRICE_AI_OVERVIEW_USD = 0.00163;
const PRICE_GOOGLE_SEARCH_USD = 0.00126;
const PRICE_WEB_SCRAPE_USD = 0.0005;

const profile = $('Confirm Your Business Profile').first().json;
const prompts = profile.buyer_prompts;
const runId = profile.run_id;

const fanout = prompts.length * (3 * PRICE_BRAND_VISIBILITY_USD + PRICE_AI_OVERVIEW_USD)
  + (TIER === 'pro' ? prompts.length * PRICE_GOOGLE_SEARCH_USD + profile.competitors.length * PRICE_GOOGLE_SEARCH_USD : 0);
const committed = Number(profile.cost_usd || 0) + fanout + PRICE_WEB_SCRAPE_USD;

if (committed > profile.spend_ceiling_usd) {
  throw new Error(
    'Stopping before the engine fan-out. ' + prompts.length + ' buyer prompts commit $' + fanout.toFixed(5)
    + ', which takes the run to $' + committed.toFixed(5) + ' against your $' + profile.spend_ceiling_usd
    + ' ceiling. Raise the ceiling or cut prompts.',
  );
}

const visibilityBody = (prompt) => ({
  prompt: prompt,
  brand: profile.brand,
  domain: profile.brand_domain,
  aliases: profile.aliases,
  competitors: profile.competitors,
  country: profile.country,
});

return prompts.map((prompt, index) => {
  const vis = visibilityBody(prompt);
  const ai = { prompt: prompt };
  return {
    json: {
      run_id: runId,
      prompt_index: index,
      prompt: prompt,
      estimated_fanout_usd: Number(fanout.toFixed(6)),
      chatgptBody: vis,
      chatgptIdem: idemKey(runId, 'chatgpt.brand_visibility', vis),
      perplexityBody: vis,
      perplexityIdem: idemKey(runId, 'perplexity.brand_visibility', vis),
      geminiBody: vis,
      geminiIdem: idemKey(runId, 'gemini.brand_visibility', vis),
      aiOverviewBody: ai,
      aiOverviewIdem: idemKey(runId, 'google.ai_overview', ai),
    },
  };
});

const TIER = 'lite';

// --- shared helpers (inlined by the builder into every Code node that needs them) ---
const MULTI_TLD = ['co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.jp', 'co.kr', 'com.br', 'co.za', 'com.sg', 'co.in', 'com.mx', 'com.tr', 'co.il'];

function hostOf(u) {
  try { return new URL(String(u)).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; }
}

function registrable(hostOrUrl) {
  const raw = String(hostOrUrl || '');
  const h = /^https?:\/\//i.test(raw) ? hostOf(raw) : raw.toLowerCase().replace(/^www\./, '').split('/')[0];
  const parts = h.split('.').filter(Boolean);
  if (parts.length <= 2) return h;
  const last2 = parts.slice(-2).join('.');
  return MULTI_TLD.indexOf(last2) === -1 ? last2 : parts.slice(-3).join('.');
}

function normalizeUrl(u) {
  try {
    const url = new URL(String(u));
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
    url.hash = '';
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    const drop = [];
    url.searchParams.forEach((_v, k) => { if (/^(utm_|fbclid|gclid|mc_|msclkid|igshid|ref$|source$)/i.test(k)) drop.push(k); });
    drop.forEach((k) => url.searchParams.delete(k));
    let s = url.toString().replace(/\?$/, '');
    if (url.pathname !== '/') s = s.replace(/\/$/, '');
    return s;
  } catch (e) { return ''; }
}

function normWs(s) { return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim(); }

function slugName(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }

function canonical(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
}

// FNV-1a style 64-bit-ish hash rendered as 16 hex chars. Pure JS on purpose: n8n Code nodes
// cannot require('crypto') unless the instance sets NODE_FUNCTION_ALLOW_BUILTIN, and a giveaway
// workflow must not depend on an instance env var.
function stableHash(value) {
  const s = typeof value === 'string' ? value : canonical(value);
  let h1 = 0x811c9dc5;
  let h2 = 0x1000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 + c, 2654435761) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

// geo-<run_id>-<sku>-<bodyHash>. Computed here as a data field, never as an inline expression on
// the HTTP node: an inline expression is re-evaluated on retry, a data field is not.
function idemKey(runId, sku, body) { return 'geo-' + runId + '-' + sku + '-' + stableHash(body); }

function safeAll(name) { try { return $(name).all(); } catch (e) { return []; } }

function safeFirst(name) { const a = safeAll(name); return a.length ? a[0].json : null; }

// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// Reads all four engine nodes by name and pairs each response back to its prompt by position.
// The merge upstream is a barrier only: pairing a merged append stream back to its prompt is
// fragile, and pairing per engine node is one to one even when an engine errors out.
//
// The rule this node applies everywhere: 200 with found:false is data absence. Mark it, count it,
// move on. Status >= 400 is failure. Record it, and stop the run only when stopping is the honest
// outcome.
const ENGINES = [
  { key: 'chatgpt', node: 'AnyAPI Ask ChatGPT', sku: 'chatgpt.brand_visibility' },
  { key: 'perplexity', node: 'AnyAPI Ask Perplexity', sku: 'perplexity.brand_visibility' },
  { key: 'gemini', node: 'AnyAPI Ask Gemini', sku: 'gemini.brand_visibility' },
  { key: 'google_ai_overview', node: 'AnyAPI Ask Google AI Overview', sku: 'google.ai_overview' },
];
// 400 is a bad body, 402 is an empty wallet, 429 is a wall. None of those get quietly degraded.
// 409 is the interesting one, and it is two different things wearing one status code:
// idempotency_conflict and idempotency_needs_review mean the key formula is broken, which is a bug
// in this workflow and worth stopping for. idempotency_in_progress just means the identical call
// is still running somewhere, which is transient and costs you one prompt on one engine.
// Measured: a re-run inside the replay window hit in_progress and killed a run it should have
// finished.
const HARD_STOP_STATUSES = [400, 402, 429];
const HARD_STOP_CODES = ['idempotency_conflict', 'idempotency_needs_review'];

const profile = $('Confirm Your Business Profile').first().json;
const calls = $('Build Visibility Calls').all().map((i) => i.json);

const answers = [];
const perEngine = {};
let cost = 0;
let empty = 0;
let failed = 0;
const hardStops = [];

ENGINES.forEach((engine) => {
  const items = safeAll(engine.node);
  perEngine[engine.key] = { ok: 0, empty: 0, failed: 0 };
  items.forEach((item, index) => {
    const call = calls[index];
    if (!call) return;
    const status = httpStatus(item);
    cost += httpCost(item);
    if (!httpOk(item)) {
      failed += 1;
      perEngine[engine.key].failed += 1;
      const code = httpErrorCode(item);
      if (HARD_STOP_STATUSES.indexOf(status) !== -1 || HARD_STOP_CODES.indexOf(code) !== -1) {
        hardStops.push(engine.sku + ' returned ' + status + ' ' + code);
      }
      return;
    }
    if (!httpFound(item)) {
      empty += 1;
      perEngine[engine.key].empty += 1;
      answers.push({ prompt: call.prompt, engine: engine.key, found: false, data: null });
      return;
    }
    perEngine[engine.key].ok += 1;
    answers.push({ prompt: call.prompt, engine: engine.key, found: true, data: httpData(item) });
  });
});

if (hardStops.length > 0) throw new Error('Stopping the run: ' + hardStops.join('; '));

const attempted = calls.length * ENGINES.length;
if (answers.filter((a) => a.found).length === 0) {
  throw new Error('No engine answered any prompt. ' + failed + ' of ' + attempted + ' calls failed and ' + empty + ' came back empty.');
}

// Your own measured visibility, which is the honest before-picture for the whole exercise.
const visibility = answers
  .filter((a) => a.found && a.engine !== 'google_ai_overview')
  .map((a) => ({
    prompt: a.prompt,
    engine: a.engine,
    mentioned: a.data.mentioned === true,
    cited: a.data.cited === true,
    shareOfVoicePct: Number(a.data.shareOfVoicePct || 0),
    citationRank: a.data.citationRank === null || a.data.citationRank === undefined ? null : Number(a.data.citationRank),
  }));

return [{
  json: {
    run_id: profile.run_id,
    answers: answers,
    visibility: visibility,
    per_engine: perEngine,
    engine_calls: attempted,
    engine_calls_empty: empty,
    engine_calls_failed: failed,
    cost_usd: Number(profile.cost_usd || 0) + cost,
  },
}];

