// The whole idea of the workflow is here. Score a page by how many distinct (prompt, engine) pairs
// cite it. A page three engines cite for two prompts is a page the models trust structurally. A
// page one engine cited once is a fluke.
const engineAnswers = $input.first().json;

const byUrl = new Map();
const touch = (url, title, snippet, pubDateUtc) => {
  const key = normalizeUrl(url);
  if (!key) return null;
  if (!byUrl.has(key)) {
    byUrl.set(key, {
      page_url: key,
      page_domain: registrable(key),
      page_title: '',
      snippet: '',
      pub_date_utc: null,
      pairs: new Set(),
      engines: new Set(),
      prompts: new Set(),
      competitor_on_page: new Set(),
    });
  }
  const row = byUrl.get(key);
  if (!row.page_title && title) row.page_title = normWs(title).slice(0, 300);
  if (!row.snippet && snippet) row.snippet = normWs(snippet).slice(0, 600);
  if (row.pub_date_utc === null && Number(pubDateUtc)) row.pub_date_utc = Number(pubDateUtc);
  return row;
};

engineAnswers.answers.filter((a) => a.found && a.data).forEach((answer) => {
  const citations = Array.isArray(answer.data.citations) ? answer.data.citations : [];
  citations.forEach((c) => {
    const row = touch(c.url, c.title, c.snippet, c.pubDateUtc || c.publishedUtc);
    if (!row) return;
    row.pairs.add(answer.prompt + '|' + answer.engine);
    row.engines.add(answer.engine);
    row.prompts.add(answer.prompt);
  });
  // competitors[].citedUrls is the richest single input the ownership filter gets: the engine has
  // already told us which cited page it attributes to a rival.
  const rivals = Array.isArray(answer.data.competitors) ? answer.data.competitors : [];
  rivals.forEach((rival) => {
    (Array.isArray(rival.citedUrls) ? rival.citedUrls : []).forEach((u) => {
      const row = touch(u, '', '', null);
      if (row) row.competitor_on_page.add(String(rival.name || '').trim());
    });
  });
});

const citations = Array.from(byUrl.values()).map((row) => ({
  page_url: row.page_url,
  page_domain: row.page_domain,
  page_title: row.page_title,
  snippet: row.snippet,
  pub_date_utc: row.pub_date_utc,
  cited_pairs: row.pairs.size,
  engines: Array.from(row.engines),
  prompts: Array.from(row.prompts),
  competitor_on_page: Array.from(row.competitor_on_page).filter(Boolean),
  discovery_source: 'citation',
}));

const domainPairs = {};
citations.forEach((c) => {
  domainPairs[c.page_domain] = (domainPairs[c.page_domain] || 0) + c.cited_pairs;
});

return [{
  json: Object.assign({}, engineAnswers, {
    citations: citations,
    citations_harvested: citations.length,
    domain_pairs: domainPairs,
  }),
}];

