// One set of names drives two later decisions: which pages are owned by somebody you cannot pitch,
// and whether a page is genuinely a multi-vendor roundup. Build it once, here.
const MIN_BRAND_TOKEN_CHARS = 3;
const STOPWORDS = new Set([
  'The', 'This', 'That', 'These', 'Those', 'They', 'There', 'Their', 'What', 'When', 'Which', 'While',
  'With', 'Without', 'For', 'From', 'Best', 'Top', 'Some', 'Most', 'Many', 'Both', 'And', 'But', 'Not',
  'You', 'Your', 'Its', 'It', 'If', 'In', 'On', 'At', 'To', 'Of', 'As', 'Is', 'Are', 'Was', 'Were',
  'Here', 'How', 'Why', 'Who', 'Whose', 'Also', 'However', 'Overall', 'Pros', 'Cons', 'Key', 'Note',
  'Free', 'Pricing', 'Price', 'Plans', 'Plan', 'Data', 'API', 'APIs', 'Tools', 'Tool', 'Software',
  'Platform', 'Platforms', 'Service', 'Services', 'Solution', 'Solutions', 'Company', 'Companies',
  // Measured additions. Every one of these was harvested as a rival on a real run and produced a
  // draft telling an editor "you already cover More".
  'More', 'Use', 'Used', 'Using', 'Need', 'Needs', 'Keep', 'Get', 'See', 'Read', 'Learn', 'Start',
  'Choose', 'Compare', 'Compared', 'Explore', 'Try', 'Search', 'Web', 'Cloud', 'Open', 'Source',
  'Enterprise', 'Modern', 'Simple', 'Fast', 'Full', 'Real', 'Support', 'Home', 'Blog', 'Docs',
]);

const harvest = $input.first().json;
const profile = $('Confirm Your Business Profile').first().json;

// Words out of your own category and your own buyer questions are not brands, they are the subject.
// Measured: without this, "Scraping" was harvested as a rival and a draft went out saying "you
// already cover Scraping there".
const OWN_VOCABULARY = new Set(
  (profile.category + ' ' + profile.icp + ' ' + profile.buyer_prompts.join(' '))
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((w) => w.length >= MIN_BRAND_TOKEN_CHARS),
);
const competitorWords = new Set(profile.competitors.join(' ').toLowerCase().split(/\s+/).filter(Boolean));

const named = new Map();
const add = (name, trusted) => {
  const s = normWs(name);
  if (!s || s.length < MIN_BRAND_TOKEN_CHARS) return;
  if (!trusted && s.toLowerCase().split(/\s+/).some((w) => OWN_VOCABULARY.has(w) && !competitorWords.has(w))) return;
  const k = s.toLowerCase();
