// Before any money is spent finding a human, prove the page is worth pitching at all.
// Two distinct vendor names is not a guess: one brand is a product page, a roundup is plural by
// definition.
const MIN_VENDORS_ON_PAGE = 2;

const brands = $('Name Every Brand In The Answers').first().json;
const profile = $('Confirm Your Business Profile').first().json;
const items = $input.all();

const yours = profile.aliases;
const rivals = brands.rival_names;
const mentions = (haystack, name) => {
  const escaped = String(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^A-Za-z0-9])' + escaped + '($|[^A-Za-z0-9])', 'i').test(haystack);
};

return items.map((item, index) => {
  const page = calls[index];
  if (!page) return { json: { skipped: true } };
  const cost = httpCost(item);
  const base = Object.assign({}, page, { cost_usd: Number(page.cost_usd || 0) + cost });
  delete base.scrapeBody;
  delete base.scrapeIdem;

  if (!httpOk(item)) {
    return { json: Object.assign(base, { status: 'scrape_failed', reject_reason: 'web.scrape returned ' + httpStatus(item) + ' ' + httpErrorCode(item) }) };
  }
  if (!httpFound(item)) {
    return { json: Object.assign(base, { status: 'scrape_empty', reject_reason: 'page returned no content' }) };
