  const data = httpData(item) || {};
  const markdown = String(data.markdown || '');
  const rawHtml = String(data.rawHtml || '');
  const flat = normWs(markdown);
  const vendorsOnPage = rivals.filter((r) => mentions(flat, r));
  const namesYou = yours.filter((a) => mentions(flat, a));

