    return { json: Object.assign(withPage, { status: 'already_listed', reject_reason: 'page already names ' + namesYou.join(', '), you_already_on_page: true }) };
  }
  if (vendorsOnPage.length < MIN_VENDORS_ON_PAGE) {
    return { json: Object.assign(withPage, { status: 'rejected_not_roundup', reject_reason: 'only ' + vendorsOnPage.length + ' named vendor on the page', you_already_on_page: false }) };
