const CONTACT_PATHS = ['/contact', '/contact-us', '/about', '/about-us', '/team', '/write-for-us', '/editorial', '/advertise'];

// Bylines are often a masthead rather than a person. "The Context Team" produced five drafts
// opening "Hi The," on a measured run, which is worse than no greeting at all. A name only counts
// as a person's when neither end of it is one of these.
const NOT_A_PERSON = new Set([
  'the', 'a', 'an', 'our', 'by', 'team', 'staff', 'editor', 'editors', 'editorial', 'admin',
  'news', 'newsroom', 'desk', 'media', 'blog', 'guest', 'contributor', 'contributors', 'author',
  'inc', 'ltd', 'llc', 'gmbh', 'co', 'company', 'group', 'labs', 'hq', 'support', 'marketing',
]);

const decode = (s) => String(s || '')
  .replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');

const firstMatch = (html, patterns) => {
  for (let i = 0; i < patterns.length; i++) {
    const m = html.match(patterns[i]);
    if (m && m[1] && normWs(decode(m[1]))) return normWs(decode(m[1]));
  }
  return '';
};

const authorFromJsonLd = (html) => {
  const blocks = html.match(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi) || [];
  for (let i = 0; i < blocks.length; i++) {
    const body = blocks[i].replace(/^[\s\S]*?>/, '').replace(/<\/script>$/i, '');
    let parsed;
    try { parsed = JSON.parse(body); } catch (e) { continue; }
    const queue = Array.isArray(parsed) ? parsed.slice() : [parsed];
    while (queue.length) {
      const node = queue.shift();
      if (!node || typeof node !== 'object') continue;
      if (Array.isArray(node['@graph'])) node['@graph'].forEach((n) => queue.push(n));
      const author = node.author;
      if (author) {
        const one = Array.isArray(author) ? author[0] : author;
        const name = typeof one === 'string' ? one : (one && one.name);
        if (name) return normWs(name);
      }
    }
  }
  return '';
};

return $input.all().map((item) => {
  const p = item.json;
  if (p.status !== 'roundup_confirmed') {
