// passes the quote gate structurally rather than by luck. It is plainer than the pro version and
// it is never wrong about what the page says.
const QUOTE_MIN_CHARS = 40;
const QUOTE_MAX_CHARS = 240;

// The candidate has to be a literal run of the page text. An earlier version stripped markdown
// characters out of the sentence before quoting it, and then the quote gate correctly refused the
// result, because a cleaned-up sentence is not a sentence that appears on the page. Measured: five
// drafts lost that way. So the cleanup is a filter now: skip noisy lines, never rewrite them.
const NOISY = /\]\(|\|\s*-{2,}|^#{1,6}\s|^\s*[-*]\s|```|!\[|<[a-z]+[ >]|^\//i;
