// workflow quoted a cookie banner and a "keep exploring as a member" upsell back at two editors.
const FURNITURE = /cookie|newsletter|subscribe|sign in|sign up|log in|min read|all rights reserved|privacy policy|terms of (use|service)|copyright|read more|share this|table of contents|skip to (main|content)|advertisement|as a member|your inbox|click (the|here)|button below|find out more|get started|book a (demo|call)|contact us|free trial/i;

