  .split(/(?<=[.!?])\s+|\n+/)
  .map((s) => s.trim())
  // A quote has to be a finished sentence. Headings, nav links and byline metadata are none of
  // them, and every one of those got quoted before this line existed.
  .filter((s) => /[.!?]$/.test(s))
  .filter((s) => s.split(/\s+/).length >= 6)
  .filter((s) => s.length >= QUOTE_MIN_CHARS && s.length <= QUOTE_MAX_CHARS)
  .filter((s) => !NOISY.test(s))
  .filter((s) => !FURNITURE.test(s))
  .filter((s) => !/^["']?\w+:\s/.test(s));

