  const p = item.json;
  const vendors = p.vendors_on_page || [];
  const sentences = sentencesOf(p.pitch_context);

  // Take the sentence that names the most vendors, not the first sentence that names one. A line
  // comparing three tools is what an editor recognises as their own work. The first match is
  // usually a stray mention in an intro.
  const named = (sentence) => vendors.filter((v) => {
    const escaped = v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return new RegExp('(^|[^A-Za-z0-9])' + escaped + '($|[^A-Za-z0-9])', 'i').test(sentence);
