    greeting,
    '',
    'I was checking which pages come up when people ask an AI assistant for the best ' + p.category + ', and yours is one of them: ' + p.page_url,
    '',
    'This line is what made me write:',
    '',
    '"' + quote + '"',
    '',
    why,
    '',
    pitchLine + ' If it is a fit for the list, I am happy to send whatever you need to evaluate it: access, pricing, or a short written summary. If it is not a fit, no problem at all and thanks for the work you already put into that page.',
    '',
    p.sender_name,
    p.sender_role + ', ' + p.brand,
    'https://' + p.brand_domain,
  ].join('\n');

  return {
    json: Object.assign({}, p, {
      pitch_source: 'template',
      pitch: { subject: subject, greeting: greeting, body: body, quotedSnippet: quote, vendorMentioned: vendor, whyRelevant: why },
