const MULTI_TLD = ['co.uk', 'org.uk', 'ac.uk', 'gov.uk', 'com.au', 'net.au', 'org.au', 'co.nz', 'co.jp', 'co.kr', 'com.br', 'co.za', 'com.sg', 'co.in', 'com.mx', 'com.tr', 'co.il'];

function hostOf(u) {
  try { return new URL(String(u)).hostname.toLowerCase().replace(/^www\./, ''); } catch (e) { return ''; }
}

function registrable(hostOrUrl) {
  const raw = String(hostOrUrl || '');
  const h = /^https?:\/\//i.test(raw) ? hostOf(raw) : raw.toLowerCase().replace(/^www\./, '').split('/')[0];
  const parts = h.split('.').filter(Boolean);
  if (parts.length <= 2) return h;
  const last2 = parts.slice(-2).join('.');
  return MULTI_TLD.indexOf(last2) === -1 ? last2 : parts.slice(-3).join('.');
}

function normalizeUrl(u) {
  try {
    const url = new URL(String(u));
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return '';
    url.hash = '';
    url.hostname = url.hostname.toLowerCase().replace(/^www\./, '');
    const drop = [];
    url.searchParams.forEach((_v, k) => { if (/^(utm_|fbclid|gclid|mc_|msclkid|igshid|ref$|source$)/i.test(k)) drop.push(k); });
    drop.forEach((k) => url.searchParams.delete(k));
    let s = url.toString().replace(/\?$/, '');
    if (url.pathname !== '/') s = s.replace(/\/$/, '');
    return s;
  } catch (e) { return ''; }
}

function normWs(s) { return String(s === null || s === undefined ? '' : s).replace(/\s+/g, ' ').trim(); }

function slugName(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ''); }

function canonical(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
}

// FNV-1a style 64-bit-ish hash rendered as 16 hex chars. Pure JS on purpose: n8n Code nodes
// cannot require('crypto') unless the instance sets NODE_FUNCTION_ALLOW_BUILTIN, and a giveaway
// workflow must not depend on an instance env var.
function stableHash(value) {
  const s = typeof value === 'string' ? value : canonical(value);
  let h1 = 0x811c9dc5;
  let h2 = 0x1000193;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 + c, 2654435761) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + h2.toString(16).padStart(8, '0');
}

// geo-<run_id>-<sku>-<bodyHash>. Computed here as a data field, never as an inline expression on
// the HTTP node: an inline expression is re-evaluated on retry, a data field is not.
function idemKey(runId, sku, body) { return 'geo-' + runId + '-' + sku + '-' + stableHash(body); }

function safeAll(name) { try { return $(name).all(); } catch (e) { return []; } }

function safeFirst(name) { const a = safeAll(name); return a.length ? a[0].json : null; }

// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// The hard gate. Twelve deterministic checks, all of them run, and a draft is only created when
// every one passes. Nothing here asks a model whether the email is fine.
// OWNER CHOICE: the four length bounds.
const SUBJECT_MIN_CHARS = 15;
const SUBJECT_MAX_CHARS = 120;
const BODY_MIN_CHARS = 250;
const BODY_MAX_CHARS = 2200;
const QUOTE_MIN_CHARS = 40;

const brands = $('Name Every Brand In The Answers').first().json;
const profile = $('Confirm Your Business Profile').first().json;
const brandsNamedLower = brands.brands_named.map((b) => b.toLowerCase());

const FAKE_HISTORY = /as (we )?discussed|following up on our (call|chat)|per our conversation|you mentioned|last time we spoke|great (call|chat)|as promised|thanks for (your time|the call)/i;
const PLACEHOLDER = /\[[A-Z_ ]{2,}\]|\{\{|<[A-Z_]{2,}>|\bTODO\b|\bXXX\b|lorem ipsum/i;
// No /i flag on purpose. With it, [A-Z] also matches lowercase, so "Hi there," reads as a
// greeting to a person called There and every anonymous draft gets rejected. Measured: 8 of them.
const NAMED_GREETING = /^(?:[Hh]i|[Hh]ey|[Hh]ello|[Dd]ear)\s+[A-Z][a-z]+/m;

return $input.all().map((item) => {
  const p = item.json;
  const failures = [];
  const pitch = p.pitch;

  if (!pitch) {
    return { json: Object.assign({}, p, { status: 'rejected_verify', reject_reason: p.pitch_missing_reason || 'no pitch was composed', verify_failures: ['no pitch'], draft_ready: false }) };
  }

  const subject = pitch.subject;
  const body = pitch.body;
  const quote = pitch.quotedSnippet;
  const context = normWs(p.pitch_context);

  // 1. The quote is really on the page, checked against the same text the writer was shown.
  if (quote.length < QUOTE_MIN_CHARS) failures.push('quote is shorter than ' + QUOTE_MIN_CHARS + ' characters');
  else if (context.indexOf(normWs(quote)) === -1) failures.push('quoted snippet is not on the page');

  // 2. The quote is actually in the email.
  if (body.indexOf(quote) === -1) failures.push('the email does not contain the quote it claims');

  // 3. The vendor named is a brand the engines named and is on the page.
  if (!pitch.vendorMentioned || brandsNamedLower.indexOf(pitch.vendorMentioned.toLowerCase()) === -1) failures.push('vendor named is not one of the brands the engines named');
  else if (normWs(p.pitch_context).toLowerCase().indexOf(pitch.vendorMentioned.toLowerCase()) === -1) failures.push('vendor named is not on the page');

  // 4. No invented links. Only the page itself and your own domain may appear.
  const urls = (subject + ' ' + body).match(/https?:\/\/[^\s<>")\]]+/g) || [];
  const strayUrl = urls.find((u) => {
    const clean = u.replace(/[.,;:)]+$/, '');
    return normalizeUrl(clean) !== p.page_url && registrable(clean) !== p.brand_domain;
  });
  if (strayUrl) failures.push('email contains a URL that is neither the page nor your site: ' + strayUrl);

  // 5. The page URL appears exactly once.
  const pageUrlCount = urls.filter((u) => normalizeUrl(u.replace(/[.,;:)]+$/, '')) === p.page_url).length;
  if (pageUrlCount !== 1) failures.push('the page URL appears ' + pageUrlCount + ' times, expected exactly once');

  // 6. The greeting matches what we actually know about the author.
  if (p.author_first) {
    if (body.indexOf(p.author_first) === -1) failures.push('the author has a first name and the email does not use it');
  } else if (NAMED_GREETING.test(body)) {
    failures.push('the email greets a person by name and no author name was found');
  }

  // 7. No invented relationship.
  if (FAKE_HISTORY.test(body)) failures.push('the email implies a relationship that does not exist');

  // 8. No faked thread.
  if (subject.indexOf('\n') !== -1) failures.push('subject is more than one line');
  if (/^(re|fwd):/i.test(subject)) failures.push('subject fakes a reply');

  // 9. No placeholders left in.
  if (PLACEHOLDER.test(subject + ' ' + body)) failures.push('email still contains a placeholder');

  // 10. It is a pitch for inclusion, so it has to name you.
  const namesYou = profile.aliases.some((a) => (subject + ' ' + body).toLowerCase().indexOf(a.toLowerCase()) !== -1);
  if (!namesYou) failures.push('the email never names your brand');

  // 11. The recipient is on the page's own domain.
  const recipientDomain = registrable(String(p.contact_email || '').split('@')[1] || '');
  if (!recipientDomain || recipientDomain !== p.page_domain) failures.push('recipient domain does not match the page domain');

  // 12. Length bounds.
  if (subject.length < SUBJECT_MIN_CHARS || subject.length > SUBJECT_MAX_CHARS) failures.push('subject length ' + subject.length + ' is outside ' + SUBJECT_MIN_CHARS + '-' + SUBJECT_MAX_CHARS);
  if (body.length < BODY_MIN_CHARS || body.length > BODY_MAX_CHARS) failures.push('body length ' + body.length + ' is outside ' + BODY_MIN_CHARS + '-' + BODY_MAX_CHARS);

  if (failures.length > 0) {
    return { json: Object.assign({}, p, { status: 'rejected_verify', reject_reason: failures[0], verify_failures: failures, draft_ready: false }) };
  }

  return {
    json: Object.assign({}, p, {
      status: 'verified',
      reject_reason: '',
      verify_failures: [],
      draft_ready: true,
      subject: subject,
      body: body,
      quoted_snippet: quote,
    }),
  };
});

