// draft:create returns the draft id plus the message id and thread id of the draft's message.
// All three get stored: the follow-up workflow reads the thread, and you need the draft id to find
// it again in Gmail.
const prospects = $('Did The Pitch Pass Every Gate?').all().map((i) => i.json);

return $input.all().map((item, index) => {
  const p = prospects[index];
  if (!p) return { json: { skipped: true } };
  const res = item.json || {};
  const message = res.message || {};
  return {
    json: Object.assign({}, p, {
      status: 'drafted',
      sequence_state: 'active',
      draft_id: String(res.id || ''),
      gmail_message_id: String(message.id || ''),
      gmail_thread_id: String(message.threadId || ''),
      draft_created_at: new Date().toISOString(),
      followups_drafted: 0,
    }),
  };
