// One place computes every number this run will report. The workbook, the summary email and the
// geo_runs row all read from here, so they cannot disagree with each other.
const profile = $('Confirm Your Business Profile').first().json;
const discovery = safeFirst('Drop Pages You Or Your Rivals Own') || {};
const prospects = $input.all().map((i) => i.json).filter((p) => !p.emptyDiscovery && p.prospect_id);

const count = (predicate) => prospects.filter(predicate).length;
const startedAt = new Date(profile.started_at).getTime();
const runtimeSeconds = Number(((Date.now() - startedAt) / 1000).toFixed(3));

const prospectCost = prospects.reduce((sum, p) => sum + Number(p.cost_usd || 0), 0);
const anyapiCost = Number((Number(discovery.cost_usd || profile.cost_usd || 0) + prospectCost).toFixed(6));

const drafted = prospects.filter((p) => p.status === 'drafted');
const visibility = discovery.visibility || [];
const citedForYou = visibility.filter((v) => v.cited).length;
const mentionedForYou = visibility.filter((v) => v.mentioned).length;

const record = {
  run_id: profile.run_id,
  started_at: profile.started_at,
  completed_at: new Date().toISOString(),
  status: 'completed',
  tier: profile.tier,
  brand: profile.brand,
  brand_domain: profile.brand_domain,
  operator_email: profile.operator_email,
  prompts_count: profile.buyer_prompts.length,
  buyer_prompts: profile.buyer_prompts,
  engine_calls: Number(discovery.engine_calls || 0),
  engine_calls_empty: Number(discovery.engine_calls_empty || 0),
  engine_calls_failed: Number(discovery.engine_calls_failed || 0),
  visibility_checks: visibility.length,
  visibility_mentioned: mentionedForYou,
  visibility_cited: citedForYou,
  citations_harvested: Number(discovery.citations_harvested || 0),
  pages_considered: Number(discovery.pages_considered || 0),
  pages_after_ownership_filter: Number(discovery.pages_after_ownership_filter || 0),
  ownership_counts: discovery.ownership_counts || {},
  pages_scraped: count((p) => ['roundup_confirmed', 'already_listed', 'rejected_not_roundup'].indexOf(p.status) !== -1 || p.scraped_at),
  pages_rejected_not_roundup: count((p) => p.status === 'rejected_not_roundup'),
  pages_already_listing_you: count((p) => p.status === 'already_listed'),
  contacts_from_page: count((p) => p.contact_source === 'page_mailto'),
  contacts_from_contact_page: count((p) => p.contact_source === 'contact_page'),
  contacts_from_email_find: count((p) => p.contact_source === 'email_find'),
  contacts_none: count((p) => p.status === 'no_contact'),
  emails_rejected: count((p) => p.status === 'rejected_email'),
  emails_verified: count((p) => ['email_verified', 'verified', 'drafted', 'rejected_verify'].indexOf(p.status) !== -1 && p.email_status),
  drafts_passed_verify: count((p) => p.draft_ready === true),
  drafts_rejected_verify: count((p) => p.status === 'rejected_verify'),
  drafts_created: drafted.length,
  anyapi_cost_usd: anyapiCost,
  spend_ceiling_usd: Number(profile.spend_ceiling_usd),
  runtime_seconds: runtimeSeconds,
  workbook_name: 'geo-prospects-' + profile.run_id + '.xlsx',
  failure_reason: '',
};

const FONT = 'font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;';
const cell = 'padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:14px;vertical-align:top;';
const head = 'padding:10px 12px;background:#111827;color:#fff;font-size:12px;text-align:left;text-transform:uppercase;letter-spacing:.04em;';
const stat = (value, label) => '<td style="padding:14px 18px;border:1px solid #e5e7eb;border-radius:8px;">'
  + '<div style="font-size:24px;font-weight:600;color:#111827;">' + value + '</div>'
  + '<div style="font-size:12px;color:#6b7280;">' + label + '</div></td><td style="width:12px;"></td>';

const rows = drafted.map((p) => '<tr>'
  + '<td style="' + cell + '">' + p.page_domain + '</td>'
  + '<td style="' + cell + 'white-space:nowrap;">' + p.contact_email + '</td>'
  + '<td style="' + cell + 'text-align:center;">' + String(p.cited_pairs) + '</td>'
  + '<td style="' + cell + '">' + p.subject + '</td>'
  + '<td style="' + cell + 'color:#374151;">' + String(p.quoted_snippet || '').slice(0, 160) + '</td>'
  + '</tr>').join('');

record.html = [
  '<div style="' + FONT + 'max-width:1040px;color:#111827;">',
