// Every AnyAPI call is sent with fullResponse + neverError, so the workflow can tell an empty
// answer (200 found:false, charged) from a failure (>=400) instead of guessing from an error item.
function httpStatus(item) { const j = item && item.json ? item.json : item; return Number(j && j.statusCode) || 0; }
function httpBody(item) { const j = item && item.json ? item.json : item; return (j && j.body) || {}; }
function httpOk(item) { const s = httpStatus(item); return s >= 200 && s < 300; }
function httpCost(item) { return httpOk(item) ? Number(httpBody(item).costUsd || 0) : 0; }
function httpFound(item) { const o = httpBody(item).output || {}; return o.found === true; }
function httpData(item) { const o = httpBody(item).output || {}; return o.data || null; }
function httpErrorCode(item) {
  const b = httpBody(item);
  const e = b && b.error;
  if (e && typeof e === 'object') return String(e.code || e.message || 'error');
  if (typeof b === 'string') return b.slice(0, 200);
  return String((b && b.code) || httpStatus(item) || 'error');
}

// Every page the run touched, including the refusals. A workbook that only shows the wins hides
// the part that tells you whether the run was any good.
const prospects = safeAll('Merge Draft Paths').map((i) => i.json).filter((p) => p.prospect_id);

// Column order is the reading order: what the page is, how much the engines trust it, what
// happened, and only then the plumbing.
const row = (p) => ({
  'Publisher': p.page_domain || '',
  'Page title': p.page_title || '',
  'Cited pairs': Number(p.cited_pairs || 0),
  'Engines': (p.engines || []).join(', '),
  'Outcome': p.status || '',
  'Why not': p.reject_reason || '',
  'Recipient': p.contact_email || '',
  'Subject': p.subject || '',
  'Quoted from the page': p.quoted_snippet || '',
  'Rivals on page': (p.vendors_on_page || p.competitor_on_page || []).join(', '),
  'Author': p.author_name || '',
  'Contact source': p.contact_source || '',
  'Email status': p.email_status || '',
  'Discovery': p.discovery_source || '',
  'Score': Number(p.score || 0),
  'Buyer prompts': (p.prompts || []).join(' | '),
  'Page URL': p.page_url || '',
  'Draft ID': p.draft_id || '',
  'Gmail thread': p.gmail_thread_id || '',
  'AnyAPI cost USD': Number(Number(p.cost_usd || 0).toFixed(6)),
});

if (prospects.length === 0) {
  return [{ json: row({ status: 'no pitchable page found', reject_reason: 'no cited page survived the ownership filter' }) }];
}

return prospects
  .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
  .map((p) => ({ json: row(p) }));

